import { forwardRef, type SelectHTMLAttributes } from "react";
import { ChevronDown } from "lucide-react";

import { cn } from "@/lib/cn";

/** Props accepted by Select. */
export type SelectProps = {
  invalid?: boolean;
} & SelectHTMLAttributes<HTMLSelectElement>;

/** A styled native select that preserves caller-owned value and event behavior. */
export const Select = forwardRef<HTMLSelectElement, SelectProps>(
  function Select({ className, invalid, ...props }, ref) {
    return (
      <span className="caps-select-shell">
        <select
          {...props}
          aria-invalid={
            invalid
              ? true
              : props["aria-invalid"] === false
                ? undefined
                : props["aria-invalid"]
          }
          className={cn(
            "select select-bordered caps-select w-full",
            invalid && "select-error",
            className,
          )}
          ref={ref}
        />
        {!props.multiple && (!props.size || props.size <= 1) ? (
          <ChevronDown className="caps-select-chevron" aria-hidden="true" />
        ) : null}
      </span>
    );
  },
);

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

.caps-select.boxShadow:
var(
      --stipe-shadow-raised,
      inset 0 1px 0 rgb(255 255 255 / calc(var(--depth) * 0.22)),
      0 calc(var(--depth) * 1px) 0
        color-mix(
          in oklab,
          var(--color-base-content) calc(var(--depth) * 16%),
          transparent
        )
    )
